const b = $input.first().json.body ?? $input.first().json;
if (!b.objektId || !b.freigegebenDurch) {
  throw new Error('Freigabe unvollständig: objektId und freigegebenDurch sind Pflicht.');
}
return [{ json: { objektId: b.objektId, freigegebenDurch: b.freigegebenDurch, zeitpunkt: b.zeitpunkt ?? new Date().toISOString(), status: 'erteilt' } }];
